    for i in range(2, n + 1):
        edges.append((1, i))
    return "\n".join(f"{u} {v}" for u, v in edges) + "\n"

def generate_incorrect_tree(n):
    if n == 2:
        return "-1\n1 2\n"
    edges = []
    for i in range(2, n + 1):
        edges.append((1, i))
    return "\n".join(f"{u} {v}" for u, v in edges) + "\n"

